// @generated by Forma (gen-viz) — do not edit manually.
// 可视化运行时 React 组件：取数 → 变换 → 整形 → 渲染 → 事件 → 响应式。
// 与图表库无关：渲染由 renderer（当前为 ECharts）承担；
// V0.2：metric（指标卡）/ table（数据表）由本文件直接渲染，不经 ECharts。

import React from "react";
import type { ChartSpec, Row, VizEventPayload } from "./spec";
import { applyTransform, shapeData } from "./transform";
import { bindData, createChart, formatValue } from "./echarts";
import "./viz.css";

export interface VizSource {
  fetch: () => Promise<Row[]>;
  /** V0.2 table widget：列定义（key/label/format） */
  columns?: Array<{ key: string; label: string; format: string }>;
}

export interface FormaChartProps {
  spec: ChartSpec;
  option: Record<string, unknown>;
  source: VizSource;
  height?: number | string;
  ariaLabel?: string;
  onEvent?: (e: VizEventPayload) => void;
  className?: string;
}

export function FormaChart({
  spec,
  option,
  source,
  height,
  ariaLabel,
  onEvent,
  className,
}: FormaChartProps) {
  // V0.2：metric / table 走 React 组件渲染（不创建 ECharts 实例）
  if (spec.chartType === "metric") {
    return <MetricCard spec={spec} source={source} className={className} />;
  }
  if (spec.chartType === "table") {
    return <TableCard spec={spec} source={source} className={className} />;
  }

  const hostRef = React.useRef<HTMLDivElement | null>(null);
  const [error, setError] = React.useState<string | null>(null);
  const [loading, setLoading] = React.useState(true);

  React.useEffect(() => {
    const el = hostRef.current;
    if (!el) return;
    let disposed = false;
    let chart: ReturnType<typeof createChart> | null = null;
    let observer: ResizeObserver | null = null;

    try {
      chart = createChart(el, spec, option, onEvent);
      observer = new ResizeObserver(() => chart?.resize());
      observer.observe(el);
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
      setLoading(false);
      return;
    }

    source
      .fetch()
      .then((rows) => {
        if (disposed || !chart) return;
        const data = shapeData(spec, applyTransform(rows ?? [], spec.transform ?? []));
        chart.setOption(bindData(option, spec, data));
        setLoading(false);
      })
      .catch((e) => {
        if (disposed) return;
        setError(e instanceof Error ? e.message : String(e));
        setLoading(false);
      });

    return () => {
      disposed = true;
      observer?.disconnect();
      chart?.dispose();
    };
  }, [spec, option, source, onEvent]);

  const boxHeight = height ?? spec.minHeight;

  return (
    <div className={className ? `forma-viz ${className}` : "forma-viz"}>
      <div
        ref={hostRef}
        className="forma-viz__canvas"
        role="img"
        aria-label={ariaLabel ?? spec.ariaLabel}
        style={{ width: "100%", height: boxHeight }}
      />
      {loading ? <p className="forma-viz__status">加载中…</p> : null}
      {error ? (
        <p className="forma-viz__error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

/** V0.2 指标卡（metric）：取数 → 变换（单个 aggregate）→ 格式化单值。 */
function MetricCard({
  spec,
  source,
  className,
}: {
  spec: ChartSpec;
  source: VizSource;
  className?: string;
}) {
  const [value, setValue] = React.useState<string>("…");
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    let disposed = false;
    source
      .fetch()
      .then((rows) => {
        if (disposed) return;
        const out = applyTransform(rows ?? [], spec.transform ?? []);
        const first = (out[0] ?? {}) as Record<string, unknown>;
        const raw = first["value"] ?? first["count"];
        const fmt = (spec as any).yAxis?.format ?? "none";
        setValue(formatValue(raw, fmt));
      })
      .catch((e) => {
        if (disposed) return;
        setError(e instanceof Error ? e.message : String(e));
        setValue("—");
      });
    return () => {
      disposed = true;
    };
  }, [spec, source]);

  return (
    <div className={className ? `forma-viz ${className}` : "forma-viz"}>
      <div className="forma-viz__metric">
        <div className="forma-viz__metric-title">{spec.title}</div>
        <div
          className="forma-viz__metric-value"
          role="img"
          aria-label={spec.ariaLabel}
        >
          {value}
        </div>
        {error ? (
          <p className="forma-viz__error" role="alert">
            {error}
          </p>
        ) : null}
      </div>
    </div>
  );
}

/** V0.2 数据表（table）：原始行以 <table> 渲染（图表的真实数据回退）。 */
function TableCard({
  spec,
  source,
  className,
}: {
  spec: ChartSpec;
  source: VizSource;
  className?: string;
}) {
  const [rows, setRows] = React.useState<Row[]>([]);
  const [error, setError] = React.useState<string | null>(null);

  React.useEffect(() => {
    let disposed = false;
    source
      .fetch()
      .then((r) => {
        if (disposed) return;
        setRows(applyTransform(r ?? [], spec.transform ?? []));
      })
      .catch((e) => {
        if (disposed) return;
        setError(e instanceof Error ? e.message : String(e));
      });
    return () => {
      disposed = true;
    };
  }, [spec, source]);

  const cols = source.columns ?? [];
  return (
    <div className={className ? `forma-viz ${className}` : "forma-viz"}>
      <div className="forma-viz__metric-title">{spec.title}</div>
      <table className="forma-viz__table">
        <thead>
          <tr>
            {cols.map((c) => (
              <th key={c.key}>{c.label}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row, i) => (
            <tr key={i}>
              {cols.map((c) => (
                <td key={c.key}>{formatValue(row[c.key], c.format)}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {error ? (
        <p className="forma-viz__error" role="alert">
          {error}
        </p>
      ) : null}
    </div>
  );
}

export default FormaChart;
